import { View } from "react-native";

import { BreakdownCard } from "./components/breakdown-card";
import { OverviewCard } from "./components/overview-card";
import {
  locations,
  visitedPagesRows,
  countriesRows,
  referrersRows,
  browsersRows,
} from "./data";

import { Text } from "@/components/ui/text";
import {
  Map,
  MapControls,
  MapGeoJSON,
  MapMarker,
  MarkerContent,
  MarkerTooltip,
} from "@/components/ui/map";

const MAP_HEIGHT = 608;

const WORLD_GEOJSON =
  "https://cdn.jsdelivr.net/gh/nvkelso/natural-earth-vector@v5.1.2/geojson/ne_110m_admin_0_countries.geojson";

export default function Page() {
  return (
    <View className="bg-background relative min-h-screen flex-1">
      <View
        className="bg-card relative"
        style={{ height: MAP_HEIGHT }}
      >
        <Map
          blank
          viewport={{ center: [-2, 16], zoom: 1.4 }}
          maxZoom={4}
          minZoom={1.4}
          scrollEnabled={false}
          rotateEnabled={false}
          pitchEnabled={false}
        >
          <MapGeoJSON
            data={WORLD_GEOJSON}
            linePaint={false}
          />
          <MapControls className="bottom-2" />
          {locations.map((location) => (
            <MapMarker
              key={location.city}
              longitude={location.lng}
              latitude={location.lat}
            >
              <MarkerContent>
                <View
                  className="bg-chart-2/80 rounded-full"
                  style={{
                    width: location.size * 3,
                    height: location.size * 3,
                  }}
                />
              </MarkerContent>
              <MarkerTooltip className="bg-popover border-border border">
                <Text className="font-medium">{location.city}</Text>
                <Text className="text-muted-foreground mt-0.5">
                  {location.size} active users
                </Text>
              </MarkerTooltip>
            </MapMarker>
          ))}
        </Map>
        <View
          className="via-background/30 to-background pointer-events-none absolute inset-x-0 bottom-0 h-40 bg-gradient-to-b from-transparent"
          accessibilityElementsHidden
        />
        <OverviewCard />
      </View>

      <View className="flex-row flex-wrap gap-4 p-4">
        <View className="min-w-[220px] flex-1">
          <BreakdownCard
            title="Visited pages"
            rows={visitedPagesRows}
          />
        </View>
        <View className="min-w-[220px] flex-1">
          <BreakdownCard
            title="Referrers"
            rows={referrersRows}
          />
        </View>
        <View className="min-w-[220px] flex-1">
          <BreakdownCard
            title="Countries"
            rows={countriesRows}
          />
        </View>
        <View className="min-w-[220px] flex-1">
          <BreakdownCard
            title="Browsers"
            rows={browsersRows}
          />
        </View>
      </View>
    </View>
  );
}

type Point = {
  x: number;
  y: number;
};

export function buildAreaPaths(
  values: number[],
  width: number,
  height: number,
): { line: string; area: string } {
  if (values.length === 0) {
    return { line: "", area: "" };
  }

  const max = Math.max(...values);
  const min = Math.min(...values);
  const range = max - min || 1;

  const points: Point[] = values.map((value, index) => {
    const x =
      values.length === 1 ? width / 2 : (index / (values.length - 1)) * width;
    const y = height - ((value - min) / range) * height;
    return { x, y };
  });

  const line = points
    .map((point, index) =>
      index === 0
        ? `M ${String(point.x)} ${String(point.y)}`
        : `L ${String(point.x)} ${String(point.y)}`,
    )
    .join(" ");

  const area = `${line} L ${String(width)} ${String(height)} L 0 ${String(height)} Z`;

  return { line, area };
}

function polarToCartesian(
  cx: number,
  cy: number,
  radius: number,
  angleDeg: number,
): Point {
  const rad = ((angleDeg - 90) * Math.PI) / 180;
  return {
    x: cx + radius * Math.cos(rad),
    y: cy + radius * Math.sin(rad),
  };
}

export function buildDonutSlicePath(
  cx: number,
  cy: number,
  innerRadius: number,
  outerRadius: number,
  startAngle: number,
  endAngle: number,
): string {
  const startOuter = polarToCartesian(cx, cy, outerRadius, endAngle);
  const endOuter = polarToCartesian(cx, cy, outerRadius, startAngle);
  const startInner = polarToCartesian(cx, cy, innerRadius, endAngle);
  const endInner = polarToCartesian(cx, cy, innerRadius, startAngle);
  const largeArc = endAngle - startAngle > 180 ? 1 : 0;

  return [
    `M ${String(startOuter.x)} ${String(startOuter.y)}`,
    `A ${String(outerRadius)} ${String(outerRadius)} 0 ${String(largeArc)} 0 ${String(endOuter.x)} ${String(endOuter.y)}`,
    `L ${String(endInner.x)} ${String(endInner.y)}`,
    `A ${String(innerRadius)} ${String(innerRadius)} 0 ${String(largeArc)} 1 ${String(startInner.x)} ${String(startInner.y)}`,
    "Z",
  ].join(" ");
}

export function buildDonutSlices(
  values: number[],
  cx: number,
  cy: number,
  innerRadius: number,
  outerRadius: number,
): string[] {
  const total = values.reduce((sum, value) => sum + value, 0) || 1;
  const paths: string[] = [];
  let angle = 0;

  for (const value of values) {
    const sweep = (value / total) * 360;
    const startAngle = angle;
    const endAngle = angle + sweep;
    paths.push(
      buildDonutSlicePath(
        cx,
        cy,
        innerRadius,
        outerRadius,
        startAngle,
        endAngle,
      ),
    );
    angle = endAngle;
  }

  return paths;
}

import { TrendingUp } from "lucide-react-native";
import { useId } from "react";
import { useColorScheme, View } from "react-native";
import Svg, { Defs, LinearGradient, Path, Stop } from "react-native-svg";

import { buildAreaPaths, buildDonutSlices } from "../chart-geometry";
import { deviceCategoryData, usersPerDay } from "../data";

import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Icon } from "@/components/ui/icon";
import { Text } from "@/components/ui/text";

const AREA_STROKE = {
  light: "#737373",
  dark: "#8a8a8a",
} as const;

function MetricChart({ color }: { color: string }) {
  const gradientId = useId().replace(/:/g, "");
  const width = 200;
  const height = 56;
  const { line, area } = buildAreaPaths(
    usersPerDay.map((day) => day.users),
    width,
    height,
  );

  return (
    <View className="h-14 w-full">
      <Svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${String(width)} ${String(height)}`}
        preserveAspectRatio="none"
      >
        <Defs>
          <LinearGradient
            id={gradientId}
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >
            <Stop
              offset="0%"
              stopColor={color}
              stopOpacity={0.4}
            />
            <Stop
              offset="100%"
              stopColor={color}
              stopOpacity={0}
            />
          </LinearGradient>
        </Defs>
        <Path
          d={area}
          fill={`url(#${gradientId})`}
        />
        <Path
          d={line}
          stroke={color}
          strokeWidth={1.5}
          fill="none"
        />
      </Svg>
    </View>
  );
}

function DeviceCategoryChart() {
  const size = 128;
  const paths = buildDonutSlices(
    deviceCategoryData.map((device) => device.value),
    size / 2,
    size / 2,
    32,
    52,
  );

  return (
    <View className="mx-auto mt-3 h-32 w-32">
      <Svg
        width={size}
        height={size}
        viewBox={`0 0 ${String(size)} ${String(size)}`}
      >
        {deviceCategoryData.map((device, index) => (
          <Path
            key={device.name}
            d={paths[index]}
            fill={device.fill}
            strokeWidth={2}
          />
        ))}
      </Svg>
    </View>
  );
}

export function OverviewCard() {
  const colorScheme = useColorScheme() === "dark" ? "dark" : "light";

  return (
    <Card className="bg-card/80 absolute top-4 left-4 z-10 w-60 gap-1">
      <CardHeader>
        <View>
          <Text className="text-muted-foreground pb-2 text-[10px] tracking-wider uppercase">
            Users in last 30 days
          </Text>
          <Text className="text-3xl leading-none font-semibold">17,234</Text>
        </View>
      </CardHeader>

      <CardContent>
        <MetricChart color={AREA_STROKE[colorScheme]} />
        <View className="mt-2 flex-row items-center gap-1.5">
          <Icon
            as={TrendingUp}
            size={12}
            className="text-foreground"
          />
          <Text className="text-foreground text-xs font-medium">+12.5%</Text>
          <Text className="text-muted-foreground text-xs">
            vs previous 30 days
          </Text>
        </View>

        <View className="border-border/60 mt-4 border-t pt-4">
          <Text className="text-muted-foreground text-[10px] tracking-wider uppercase">
            Device category in last 30 days
          </Text>

          <DeviceCategoryChart />

          <View className="mt-3 flex-row gap-2">
            {deviceCategoryData.map((device) => (
              <View
                key={device.name}
                className="flex-1 items-center"
              >
                <View className="flex-row items-center justify-center gap-1.5">
                  <View
                    className="size-2 rounded-full"
                    style={{ backgroundColor: device.fill }}
                  />
                  <Text className="text-muted-foreground text-[10px] tracking-wide uppercase">
                    {device.name}
                  </Text>
                </View>
                <Text className="text-foreground mt-1 leading-none font-medium tabular-nums">
                  {device.value}%
                </Text>
              </View>
            ))}
          </View>
        </View>
      </CardContent>
    </Card>
  );
}

import { View } from "react-native";

import { type BreakdownRow } from "../data";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Text } from "@/components/ui/text";

interface BreakdownCardProps {
  title: string;
  rows: BreakdownRow[];
}

export function BreakdownCard({ title, rows }: BreakdownCardProps) {
  const maxRowValue =
    rows.length > 0 ? Math.max(...rows.map((row) => row.value)) : 0;

  return (
    <Card className="gap-2">
      <CardHeader>
        <CardTitle className="text-sm font-medium">{title}</CardTitle>
      </CardHeader>

      <CardContent>
        <View className="mb-2 flex-row items-center justify-between">
          <Text className="text-muted-foreground text-[11px] tracking-wider uppercase">
            {title}
          </Text>
          <Text className="text-muted-foreground text-[11px] tracking-wider uppercase">
            Visitors
          </Text>
        </View>
        <View className="gap-1.5">
          {rows.map((row) => {
            const pct = maxRowValue ? (row.value / maxRowValue) * 100 : 0;
            return (
              <View
                key={row.label}
                className="relative flex-row items-center justify-between overflow-hidden rounded-md px-2 py-1.5"
              >
                <View
                  className="bg-chart-2/20 absolute inset-y-0 left-0 rounded-md"
                  style={{ width: `${pct}%` }}
                />
                <Text
                  className="text-foreground/90 relative pr-2 text-xs"
                  numberOfLines={1}
                >
                  {row.label}
                </Text>
                <Text className="text-foreground relative text-xs font-medium tabular-nums">
                  {row.value.toLocaleString()}
                </Text>
              </View>
            );
          })}
        </View>
      </CardContent>
    </Card>
  );
}
